insert into sale_results select lives_ok($$select public.save_admin_sale_draft(null,' Cliente ','pix','[{"product_id":"de630000-0000-4000-8000-000000000001","quantity":"2.000","unit_price":"4.50"},{"product_id":"de630000-0000-4000-8000-000000000002","quantity":"3.000","unit_price":"2.00"}]')$$,'draft with multiple items saved');
insert into sale_results select is((select count(*) from public.stock_movements where source_type='sale'),0::bigint,'draft does not change stock');
insert into sale_results select is((select total_amount from public.sales where customer_name='Cliente'),15::numeric,'total recalculated');
insert into sale_results select is((select count(*) from public.sale_items),2::bigint,'multiple items persisted');
insert into sale_results select throws_ok($$select public.save_admin_sale_draft(null,null,'pix','[{"product_id":"de630000-0000-4000-8000-000000000001","quantity":1,"unit_price":1},{"product_id":"de630000-0000-4000-8000-000000000001","quantity":2,"unit_price":1}]')$$,'22023','sale_item_invalid','duplicate rejected');
insert into sale_results select throws_ok($$select public.save_admin_sale_draft(null,null,'pix','[{"product_id":"de630000-0000-4000-8000-000000000003","quantity":1,"unit_price":1}]')$$,'42501','sale_unauthorized','cross tenant rejected');
insert into sale_results select throws_ok($$select public.save_admin_sale_draft(null,null,'pix','[{"product_id":"de630000-0000-4000-8000-000000000001","quantity":0,"unit_price":1}]')$$,'22023','sale_item_invalid','zero quantity rejected');
insert into sale_results select throws_ok($$select public.save_admin_sale_draft(null,null,'pix','[{"product_id":"de630000-0000-4000-8000-000000000001","quantity":1,"unit_price":-1}]')$$,'22023','sale_item_invalid','negative price rejected');
insert into sale_results select lives_ok($$select public.complete_admin_sale((select id from public.sales where customer_name='Cliente'))$$,'completion succeeds');
insert into sale_results select is((select count(*) from public.stock_movements where source_type='sale'),2::bigint,'one movement per item');
insert into sale_results select is((select movement_type||':'||source_type||':'||quantity_delta::text from public.stock_movements where product_id='de630000-0000-4000-8000-000000000001'),'sale:sale:-2.000','sale ledger origin and negative delta');
insert into sale_results select is((select quantity from public.product_stock_balances where product_id='de630000-0000-4000-8000-000000000001'),-2::numeric,'negative stock allowed');
insert into sale_results select ok((select status='completed' and completed_at is not null from public.sales where customer_name='Cliente'),'completion updates status');
insert into sale_results select throws_ok($$select public.complete_admin_sale((select id from public.sales where customer_name='Cliente'))$$,'55000','sale_already_completed','double completion rejected');
insert into sale_results select is((select count(*) from public.stock_movements where source_type='sale'),2::bigint,'double completion does not duplicate');
insert into sale_results select throws_ok($$update public.sale_items set quantity=9 where product_id='de630000-0000-4000-8000-000000000001'$$,'55000','sale_completed_read_only','completed items immutable');
insert into sale_results select is((select count(*) from public.sales),0::bigint,'management false hides sales');
insert into sale_results select throws_ok($$select public.save_admin_sale_draft(null,null,'pix','[{"product_id":"de630000-0000-4000-8000-000000000001","quantity":1,"unit_price":1}]')$$,'42501','sale_unauthorized','management false blocks writes');
insert into sale_results select throws_ok($$select * from public.sales$$,'42501',null,'anon cannot read sales');
insert into sale_results select ok(not has_table_privilege('service_role','public.sales','SELECT,INSERT,UPDATE,DELETE'),'service role receives no sale grants');
insert into sale_results select * from finish(); select result from sale_results; rollback;
